/* @lc app=leetcode id=2012 lang=kotlin */ class Solution { fun sumOfBeauties(nums: IntArray): Int = IntArray(nums.size).also { rMin -> rMin[nums.size - 1] = nums[nums.size - 1] }.also { rMin -> (nums.size - 2 downTo 0).forEach { i -> rMin[i] = minOf(rMin[i + 1], nums[i]) } }.let { rMin -> intArrayOf(nums[0], 0).also { v -> (1 until nums.size - 1).forEach { i -> v.also { if (nums[i] > v[0] && nums[i] < rMin[i + 1]) v[1] += 2 else if (nums[i] > nums[i - 1] && nums[i] < nums[i + 1]) v[1] += 1 }.also { if (nums[i] > v[0]) v[0] = nums[i] } } }[1] } }